import{_ as o,o as t,c as r,a0 as a}from"./chunks/framework.CNDWyMYS.js";const k=JSON.parse('{"title":"luarocks","description":"","frontmatter":{},"headers":[],"relativePath":"luarocks.md","filePath":"luarocks.md"}'),l={name:"luarocks.md"};function s(c,e,i,n,d,u){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="luarocks" tabindex="-1">luarocks <a class="header-anchor" href="#luarocks" aria-label="Permalink to &quot;luarocks&quot;">​</a></h1><p><strong>luarocks</strong> is the command-line interface for LuaRocks, the Lua package manager.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>luarocks [--server=&lt;server&gt; | --only-server=&lt;server&gt;] [--tree=&lt;tree&gt;] [--only-sources=&lt;url&gt;] [--deps-mode=&lt;mode&gt;] [&lt;VAR&gt;=&lt;VALUE&gt;]... &lt;command&gt; [&lt;argument&gt;]</span></span></code></pre></div><p>Variables from the &quot;variables&quot; table of the <a href="./config_file_format.html">configuration file</a> can be overridden with <code>VAR=VALUE</code> assignments.</p><h3 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h3><ul><li><code>--server=&lt;server&gt;</code>: Fetch rocks/rockspecs from this server (takes priority over config file).</li><li><code>--only-server=&lt;server&gt;</code>: Fetch rocks/rockspecs from this server only (overrides any entries in the config file).</li><li><code>--only-sources=&lt;url&gt;</code>: Restrict downloads of sources to URLs starting with the given URL. For example, <code>--only-sources=https://luarocks.org</code> will allow LuaRocks to download sources only if the URL given in the rockspec starts with <code>https://luarocks.org</code>.</li><li><code>--tree=&lt;tree&gt;</code>: Which tree to operate on.</li><li><code>--local</code>: Use the tree in the user&#39;s home directory. To enable it, see <a href="./luarocks_path.html"><code>luarocks path</code></a>.</li><li><code>--deps-mode=&lt;mode&gt;</code>: Select dependencies mode: <ul><li><strong>one</strong>: Consider only the tree at the top of the list (possibly, the one given by the <code>--tree</code> flag, overriding all entries from <code>rocks_trees</code>).</li><li><strong>all</strong>: Consider all trees: if a dependency is installed in any tree of the <code>rocks_trees</code> list, we have a positive match.</li><li><strong>order</strong>: Consider only trees starting from the &quot;current&quot; one in the order, where the &quot;current&quot; is either: <ul><li>the one at the bottom of the <code>rocks_trees</code> list,</li><li>or one explicitly given with <code>--tree</code>,</li><li>or the &quot;home&quot; tree if <code>--local</code> was given or <code>local_by_default=true</code> is configured (usually at the top of the list).</li></ul></li></ul></li><li><code>--verbose</code>: Display verbose output of commands executed.</li><li><code>--timeout</code>: Timeout on network operations, in seconds. <code>0</code> means no timeout (wait forever). Default is <code>30</code>.</li></ul><hr><h2 id="supported-commands" tabindex="-1">Supported Commands <a class="header-anchor" href="#supported-commands" aria-label="Permalink to &quot;Supported Commands&quot;">​</a></h2><ul><li><strong><a href="./luarocks_build.html">build</a></strong>: Build/compile and install a rock.</li><li><strong><a href="./luarocks_doc.html">doc</a></strong>: Shows documentation for an installed rock.</li><li><strong><a href="./luarocks_download.html">download</a></strong>: Download a specific rock or rockspec file from a rocks server.</li><li><strong><a href="./luarocks_help.html">help</a></strong>: Help on commands.</li><li><strong><a href="./luarocks_install.html">install</a></strong>: Install a rock.</li><li><strong><a href="./luarocks_lint.html">lint</a></strong>: Check syntax of a rockspec.</li><li><strong><a href="./luarocks_list.html">list</a></strong>: Lists currently installed rocks.</li><li><strong><a href="./luarocks_config.html">config</a></strong>: Query and set the LuaRocks configuration.</li><li><strong><a href="./luarocks_make.html">make</a></strong>: Compile package in the current directory using a rockspec and install it.</li><li><strong><a href="./luarocks_new_version.html">new_version</a></strong>: Auto-write a rockspec for a new version of a rock.</li><li><strong><a href="./luarocks_pack.html">pack</a></strong>: Create a rock, packing sources or binaries.</li><li><strong><a href="./luarocks_path.html">path</a></strong>: Return the currently configured package path.</li><li><strong><a href="./luarocks_purge.html">purge</a></strong>: Remove all installed rocks from a tree.</li><li><strong><a href="./luarocks_remove.html">remove</a></strong>: Uninstall a rock.</li><li><strong><a href="./luarocks_search.html">search</a></strong>: Query the LuaRocks repositories.</li><li><strong><a href="./luarocks_test.html">test</a></strong>: Run the test suite in the current directory.</li><li><strong><a href="./luarocks_show.html">show</a></strong>: Shows information about an installed rock.</li><li><strong><a href="./luarocks_unpack.html">unpack</a></strong>: Unpack the contents of a rock.</li><li><strong><a href="./luarocks_upload.html">upload</a></strong>: Upload a rockspec to the public rocks repository.</li><li><strong><a href="./luarocks_write_rockspec.html">write_rockspec</a></strong>: Write a template for a rockspec file.</li></ul><hr><h2 id="overview-of-the-difference-between-make-build-install-and-pack" tabindex="-1">Overview of the Difference Between <code>make</code>, <code>build</code>, <code>install</code>, and <code>pack</code> <a class="header-anchor" href="#overview-of-the-difference-between-make-build-install-and-pack" aria-label="Permalink to &quot;Overview of the Difference Between `make`, `build`, `install`, and `pack`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><code>luarocks install modulename</code></td><td>Downloads a binary <code>.rock</code> file and installs it to the local tree (falls back to <code>luarocks build modulename</code> behavior if a binary rock is not found).</td></tr><tr><td><code>luarocks build modulename</code></td><td>Downloads a <code>.src.rock</code> or a rockspec and builds+installs it to the local tree.</td></tr><tr><td><code>luarocks build modulename-1.0-1.linux-x86.rock</code></td><td>Extracts the rockspec from the rock and builds it as if the rockspec was passed in the command-line (i.e., redownloading sources and recompiling C modules if any).</td></tr><tr><td><code>luarocks build modulename-1.0-1.rockspec</code></td><td>Builds+installs the rock using the given rockspec, downloading the sources.</td></tr><tr><td><code>luarocks make modulename-1.0-1.rockspec</code></td><td>Builds+installs the rock using the rockspec and the contents of your current directory (kind of like the way <code>make</code> uses a Makefile) instead of downloading sources.</td></tr><tr><td><code>luarocks pack modulename</code></td><td>Grabs the rock from your local tree and packs it into a binary <code>.rock</code> file.</td></tr><tr><td><code>luarocks pack modulename-1.0-1.rockspec</code></td><td>Downloads the sources from the URL and packs it into a <code>.src.rock</code> file.</td></tr></tbody></table>',13)])])}const m=o(l,[["render",s]]);export{k as __pageData,m as default};
